import sys,json,math,argparse,time,os
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot

PAPER=0.227185
Z_SAFE=0.065
Z_PAINT=0.0155
Q=np.array([0.,1.,0.,0.])
WELLS=[]
for col in range(2):
 for row in range(6): WELLS.append(np.array([-.16+.022*row,.140+.022*col,.022]))
for row in range(1,5): WELLS.append(np.array([-.16+.022*row,.184,.022]))

def pix_to_world(u,v,z):
 return np.array([.0135925-(v+.5)*PAPER/1024,.1135925-(u+.5)*PAPER/1024,z])

def lerp(a,b,max_step):
 n=max(1,math.ceil(float(np.linalg.norm(np.asarray(b)-a))/max_step))
 return [np.asarray(a)+(np.asarray(b)-a)*k/n for k in range(1,n+1)]

class Painter:
 def __init__(self):
  self.r=Robot();o=self.r.get_obs();self.p=np.array(o.meta['proprio']['now'][7:10]);self.color=None
  print('connected',self.r.status(),'tip',self.p,flush=True)
 def submit(self,pts):
  a=np.array([np.r_[p,Q] for p in pts],dtype=float)
  while True:
   try:
    x=self.r.submit('ee_pose',a,dt=.1,video='none')
    fails=sum(v['ik_failures'] for v in x.meta['plan'])
    if fails: print('IK failures',fails,flush=True)
    self.p=np.array(pts[-1]);return x
   except Exception as e:
    print('submit error, waiting for same episode',repr(e),flush=True)
    self.r.wait_ready(); print('resumed',self.r.status(),flush=True)
 def move(self,dest,step=.016,hold=2):
  pts=lerp(self.p,np.array(dest),step)+[np.array(dest)]*hold
  self.submit(pts)
 def dip(self,col):
  w=WELLS[col-1];high=w.copy();high[2]=Z_SAFE
  # Move across the table only at a safe height.
  if self.p[2]<.05:self.move([self.p[0],self.p[1],Z_SAFE])
  self.move(high)
  self.move(w,step=.006,hold=4)
  self.move(high,step=.006,hold=3)
  self.color=col
 def stroke(self,s):
  col=s['paint']
  if self.color!=col:self.dip(col)
  a=pix_to_world(s['u'],s['v0'],Z_PAINT);b=pix_to_world(s['u'],s['v1'],Z_PAINT)
  ah=a.copy();ah[2]=Z_SAFE;bh=b.copy();bh[2]=Z_SAFE
  if self.p[2]<.05:self.move([self.p[0],self.p[1],Z_SAFE])
  # A single call per painted contact; safe travel, entry, contact, exit.
  pts=lerp(self.p,ah,.016)+[ah]*2
  pts+=lerp(ah,a,.006)+[a]*3
  pts+=lerp(a,b,.0035)+[b]*3
  pts+=lerp(b,bh,.006)+[bh]*3
  if len(pts)>100:raise RuntimeError(('stroke too long',len(pts),s))
  self.submit(pts)
 def park(self):
  if self.p[2]<.05:self.move([self.p[0],self.p[1],Z_SAFE])
  self.move([-.1,.2,.1],hold=5)

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--limit',type=int,default=10000);ap.add_argument('--snapshot',action='store_true');args=ap.parse_args()
 raw=json.load(open('/app/output/plan.json'))
 # Lay in light areas first; shadows and outlines stay legible on top.
